CustomField.formula:
IF( ISBLANK( Last_Modified_Date_Status__c ) , 
IF(AND((Lead_age_Hours__c <= 1*24), ISPICKVAL(Status, 'New')), 
    IMAGE("/resource/sked_HLT_Dist/images/Green.png", "Green", 25, 92), 
    IF(AND((Lead_age_Hours__c >= 1*24), (Lead_age_Hours__c < 2*24), ISPICKVAL(Status, 'New')),
        IMAGE("/resource/sked_HLT_Dist/images/Amber.png", "Amber", 25, 92),
        IF(AND((Lead_age_Hours__c >= 2*24), ISPICKVAL(Status, 'New')),
            IMAGE("/resource/sked_HLT_Dist/images/Red.png", "Red", 25, 92),
            IF(AND((Lead_age_Hours__c <= 1*24), ISPICKVAL(Status, 'Contacted')),
                IMAGE("/resource/sked_HLT_Dist/images/Green.png", "Green", 25, 92),
                IF( AND(((ABS((NOW() - CreatedDate)*24)) >= 1*24), (Lead_age_Hours__c < 2*24), ISPICKVAL(Status, 'Contacted')),
                    IMAGE("/resource/sked_HLT_Dist/images/Amber.png", "Amber", 25, 92),
                    IF(AND((Lead_age_Hours__c >= 2*24), ISPICKVAL(Status, 'Contacted')),
                        IMAGE("/resource/sked_HLT_Dist/images/Red.png", "Red", 25, 92),
                        IF(AND(((ABS((NOW() - CreatedDate)*24)) <= 5*24), ISPICKVAL(Status, 'Qualified')),
                            IMAGE("/resource/sked_HLT_Dist/images/Green.png", "Green", 25, 92),
                            IF(AND((Lead_age_Hours__c > 5*24), (Lead_age_Hours__c <= 6*24), ISPICKVAL(Status, 'Qualified')),
                                IMAGE("/resource/sked_HLT_Dist/images/Amber.png", "Amber", 25, 92),
                                IF(AND((Lead_age_Hours__c > 6*24), ISPICKVAL(Status, 'Qualified')),
                                    IMAGE("/resource/sked_HLT_Dist/images/Red.png", "Red", 25, 92),
                                    IF(AND((Lead_age_Hours__c <= 28*24), ISPICKVAL(Status, 'Converted')),
                                        IMAGE("/resource/sked_HLT_Dist/images/Green.png", "Green", 25, 92),
                                        IF(AND((Lead_age_Hours__c > 28*24), (Lead_age_Hours__c <= 29*24), ISPICKVAL(Status, 'Converted')),IMAGE("/resource/sked_HLT_Dist/images/Amber.png", "Amber", 25, 92),IF(AND(((ABS((NOW() - CreatedDate)*24)) >= 30*24), ISPICKVAL(Status, 'Converted')),IMAGE("/resource/sked_HLT_Dist/images/Red.png", "Red", 25, 92),IMAGE("/resource/Grey", "Grey", 25, 92)
                                            )
                                        )
                                    )
                                )
                            )
                        )
                    )
                )
            )
        )
    )
),Lead_Stage_Status_Updated__c)
